import '../contact/Contact.css';
import React from 'react';
import { Form, Col, Row, Button } from 'react-bootstrap';
import { useState } from 'react';
import Msgmodal from '../../components/modals/Msgmodal';
import AlertMsg from '../../components/modals/AlertMsg';
const Contact = () => {
    const [modalShow, setModalShow] = useState(false);
    const [firstName,setFirstName] = useState("");
    const [lastName,setLastName] = useState("");
    const [email,setEmail] = useState("");
    const [message,setMessage] = useState("");
    const [data,setData] = useState([]);
    const [show, setShow] = useState(false);

    const submitHandler = (e) => {
        e.preventDefault();

        const newUser = {
            firstName: firstName,
            lastName: lastName,
            email: email,
            message: message
        }
        setData([...data, newUser]);
        setFirstName("");
        setLastName("");
        setEmail("");
        setMessage("");
        if (firstName === '' || lastName === '' || email === '' || message === ''){
        // Display an error message if any of the fields are empty
        setShow(true);
        setModalShow(false);
        /*alert('All fields are required');*/

        }
        // If the form is valid, open the modal
        else 
        setModalShow(true);
        setShow(false);
    };

    return (
        <>
            <Form className="container border border-primary border-2 rounded-3 col-lg-7 col-11 mt-auto p-2 text-white bg-info bg-opacity-10" onSubmit={submitHandler}>

                <Row className="mb-3">
                    <Form.Group as={Col} controlId="firstName">
                        <Form.Label>First Name</Form.Label>
                        <Form.Control type="text" placeholder="First Name" value={firstName} required />
                    </Form.Group>

                    <Form.Group as={Col} controlId="lastName">
                        <Form.Label>Last Name</Form.Label>
                        <Form.Control type="text" placeholder="Last Name" value={lastName} required />
                    </Form.Group>
                </Row>

                <Form.Group className="mb-3" controlId="email">
                    <Form.Label>Email</Form.Label>
                    <Form.Control type="email" placeholder="Email" value={email} required />
                </Form.Group>

                <Form.Group className="mb-3" controlId="message">
                    <Form.Label>Your Message</Form.Label>
                    <Form.Control as="textarea" aria-label="With textarea" value={message} required/>
                </Form.Group>

                <div className="text-center">

                    <Button variant="danger" type='submit' onClick={submitHandler}>
                        Send
                    </Button>
                   <Msgmodal show={modalShow} onHide={()=> setModalShow(false)}/>
                   <Alert show={show} onHide={()=> setShow(false)}/>
                </div>

                            <Alert variant="danger" onClick={submitHandler}>
                            Please fill out all required fields test.
                        </Alert>

            </Form>

        </>
    );
}

export default Contact;
